import { ExecutorRuntimePreparationError } from "./executor-runtime-prepare-schema.js";
import { createPreparedHostedRuntimeAgent } from "./default-chat-runtime.js";
import { getProjectAgentRuntimeInlineTools, runWithProjectAgentRuntime, } from "../project/agent-runtime.js";
import { isToolVisibleTo } from "../../tool/executor.js";
import { isSkillInfrastructureToolId } from "../../skill/types.js";
import { filterPrivateArray } from "../../security/private-array.js";
import { copyPrivateMap } from "../../security/private-map.js";
import { chainPrivatePromise, resolvePrivatePromise } from "../../security/private-promise.js";
import { createRuntimePreparationCore, } from "./runtime-preparation-core.js";
const mapGet = Map.prototype.get;
const apply = Reflect.apply;
const fromEntries = Object.fromEntries;
/** Preserve executor-local discovery and preparation without duplicating runtime policy. */
export function createExecutorRuntimePreparation(input) {
    const discovery = input.discovery;
    let runtime;
    const owner = createRuntimePreparationCore({
        binding: input.binding,
        source: input.source,
        grant: input.grant,
        facades: input.facades,
        project: {
            signal: discovery.signal,
            async prepare(agentId, context) {
                const operation = apply(mapGet, discovery.operations, ["agent.describe"]);
                if (operation?.mode !== "unary") {
                    throw new ExecutorRuntimePreparationError("EXECUTOR_RUNTIME_CAPABILITY_UNAVAILABLE");
                }
                const description = await chainPrivatePromise(resolvePrivatePromise(), () => operation.handle({ agentId }, context));
                runtime = discovery.getRuntime();
                const selectedRuntime = runtime;
                return runWithProjectAgentRuntime(selectedRuntime, () => {
                    const localTools = copyPrivateMap(selectedRuntime.tools);
                    for (const [name, tool] of getProjectAgentRuntimeInlineTools(selectedRuntime, agentId)) {
                        localTools.set(name, tool);
                    }
                    return {
                        __proto__: null,
                        description,
                        localTools: fromEntries(filterPrivateArray([...localTools], ([id, value]) => !isSkillInfrastructureToolId(id) && isToolVisibleTo(value, { agentId }))),
                        sourceIntegrationPolicy: selectedRuntime.sourceIntegrationPolicy,
                    };
                });
            },
            instantiate: (options, runtimeOptions) => {
                if (!runtime)
                    throw new ExecutorRuntimePreparationError("EXECUTOR_RUNTIME_NOT_PREPARED");
                return runWithProjectAgentRuntime(runtime, () => createPreparedHostedRuntimeAgent(options, runtimeOptions));
            },
            retainTask: (task) => discovery.retainRuntimeTask(task),
            close: () => discovery.close(),
        },
    });
    return { ...owner, operations: new Map([...discovery.operations, ...owner.operations]) };
}
